def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 99:
        return 'D'

    opp_def = 0
    my_def = 0
    for m, o in history:
        if o == 'D':
            opp_def += 1
        if m == 'D':
            my_def += 1

    opp_def_rate = opp_def / n

    recent_def = 0
    start = n - 5
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            recent_def += 1

    unprovoked = 0
    provoked = 0
    for i in range(n - 1):
        if history[i][0] == 'C' and history[i + 1][1] == 'D':
            unprovoked += 1
        if history[i][0] == 'D' and history[i + 1][1] == 'D':
            provoked += 1

    if opp_def_rate > 0.8:
        return 'D'

    if unprovoked >= 4 and unprovoked > provoked * 2:
        return 'D'

    forgiven = 0
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i][1] == 'C' and history[i + 1][1] == 'C':
            forgiven += 1

    if opp_def == 0:
        if forgiven >= 3:
            return 'D'
        if forgiven >= 2 and n % 3 == 0:
            return 'D'
        if forgiven >= 1 and n % 5 == 0:
            return 'D'
        if n % 8 == 0:
            return 'D'

    last_m, last_o = history[-1]

    if last_o == 'D':
        if last_m == 'C' and (n < 2 or history[-2][0] == 'C'):
            return 'D'
        else:
            return 'C'

    if last_m == 'D':
        last_my_def = -1
        for i in range(n - 1, -1, -1):
            if history[i][0] == 'D':
                last_my_def = i
                break
        if last_my_def == n - 1:
            return 'C'
        retaliated = False
        for i in range(last_my_def + 1, n):
            if history[i][1] == 'D':
                retaliated = True
                break
        if not retaliated and opp_def == 0:
            return 'D'
        else:
            return 'C'

    return 'C'
